                if (res.statusCode && res.statusCode >= 400) {
                    return reject(new HttpError(res.statusCode, res.statusMessage));
                }

                const chunks: Buffer[] = [];
                res.on('data', chunk => {
                    chunks.push(Buffer.from(chunk));
                    // Optimization: Stop downloading once we have enough for the header
                    const currentBuffer = Buffer.concat(chunks);
                    try {
                        const dimensions = imageSize(currentBuffer);
                        if (dimensions?.width && dimensions?.height) {
                            res.destroy(); // Abort the rest of the download
                            resolve({ width: dimensions.width, height: dimensions.height });
                        }
                    } catch {
                        // Not enough data yet, keep downloading
                    }
                });

                res.on('end', () => {
                    if (chunks.length > 0) {
                        try {
                            const buffer = Buffer.concat(chunks);
                            const dimensions = imageSize(buffer);
                            if (dimensions?.width && dimensions?.height) {
                                resolve({ width: dimensions.width, height: dimensions.height });
                            } else {
                                reject(new Error('Image has no size'));
                            }
                        } catch (err) {
                            reject(err);
                        }
                    }
                });

                res.on('error', reject);
